/** Fill every 4x4 belt slot with the demo potion of its column. */
export function seedDemoBeltPotions<T extends BeltModel>(belt: T): T {
  for (let row = 0; row < BELT_ROWS; row++) {
    for (let col = 0; col < BELT_COLS; col++) {
      const template = DEMO_BELT_POTIONS[col]!
      belt.grid[row]![col] = { ...template, id: `${template.id}-r${row}-c${col}` }
    }
  }
  return belt
}
